import React, { useEffect, useRef, useState } from 'react';
import { TECH_ICONS } from '../constants';

const TechSphere: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const requestRef = useRef<number>(0);
  const iconsRef = useRef<(HTMLDivElement | null)[]>([]);
  const hoveredIndex = useRef<number | null>(null);
  const [radius, setRadius] = useState(180);
  const [tilt, setTilt] = useState({ x: 0, y: 0 });
  const rotation = useRef({ x: 0, y: 0 });
  const velocity = useRef({ x: 0, y: 0 });
  const mouse = useRef({ x: 0, y: 0 });
  const scrollSpeed = useRef(0);
  const baseSpeed = 0.002;
  const friction = 0.05;

  useEffect(() => {
    const handleResize = () => {
      const width = window.innerWidth;
      if (width < 640) setRadius(130);
      else if (width < 1024) setRadius(170);
      else setRadius(220);
    };
    handleResize();
    window.addEventListener('resize', handleResize);

    const updateMouse = (clientX: number, clientY: number) => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const x = (clientX - (rect.left + rect.width / 2)) / (window.innerWidth / 2);
      const y = (clientY - (rect.top + rect.height / 2)) / (window.innerHeight / 2);
      mouse.current = { x, y };
      setTilt({ x: x * 5, y: -y * 5 });
    };

    const handleMouseMove = (e: MouseEvent) => updateMouse(e.clientX, e.clientY);
    const handleScroll = () => { scrollSpeed.current = 0.03; };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('scroll', handleScroll);

    // Initial Position Calculation
    const count = TECH_ICONS.length;
    const phi = Math.PI * (3 - Math.sqrt(5));
    iconsRef.current.forEach((item, i) => {
      if (!item) return;
      const y = 1 - (i / (count - 1)) * 2;
      const radiusAtY = Math.sqrt(1 - y * y);
      const theta = phi * i;
      item.dataset.nx = (Math.cos(theta) * radiusAtY).toString();
      item.dataset.ny = y.toString();
      item.dataset.nz = (Math.sin(theta) * radiusAtY).toString();
    });

    const animate = () => {
      scrollSpeed.current *= 0.95;
      velocity.current.x += (mouse.current.y * 0.005 - velocity.current.x) * friction;
      velocity.current.y += (mouse.current.x * 0.005 - velocity.current.y) * friction;
      rotation.current.x += velocity.current.x + scrollSpeed.current;
      rotation.current.y += velocity.current.y + baseSpeed + scrollSpeed.current;

      const cx = Math.cos(rotation.current.x);
      const sx = Math.sin(rotation.current.x);
      const cy = Math.cos(rotation.current.y);
      const sy = Math.sin(rotation.current.y);

      iconsRef.current.forEach((item, i) => {
        if (!item) return;
        const nx = parseFloat(item.dataset.nx || '0');
        const ny = parseFloat(item.dataset.ny || '0');
        const nz = parseFloat(item.dataset.nz || '0');
        const ry = ny * cx - nz * sx;
        const rz1 = ny * sx + nz * cx;
        const rx = nx * cy + rz1 * sy;
        const rz = -nx * sy + rz1 * cy;

        const finalX = rx * radius;
        const finalY = ry * radius;
        const finalZ = rz * radius;
        const scale = 400 / (400 - finalZ);
        const alpha = (finalZ + radius) / (2 * radius);
        const scaleMultiplier = hoveredIndex.current === i ? 1.3 : 1;

        item.style.transform = `translate3d(${finalX}px, ${finalY}px, ${finalZ}px) scale(${scale * scaleMultiplier})`;
        item.style.opacity = Math.max(0.15, alpha + 0.1).toString();
        item.style.zIndex = Math.floor(scale * 100).toString();
      });
      requestRef.current = requestAnimationFrame(animate);
    };
    animate();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(requestRef.current);
    };
  }, [radius]);

  return (
    <div className="relative flex items-center justify-center perspective-1000" style={{ width: radius * 2.5, height: radius * 2.5 }}>
      <div ref={containerRef} className="relative w-full h-full transform-style-3d transition-transform duration-700 ease-out" style={{ transform: `rotateX(${tilt.y}deg) rotateY(${tilt.x}deg)` }}>
        {TECH_ICONS.map((tech, i) => (
          <div key={i} ref={(el) => { iconsRef.current[i] = el; }} onMouseEnter={() => { hoveredIndex.current = i; }} onMouseLeave={() => { hoveredIndex.current = null; }} className="absolute top-1/2 left-1/2 -ml-6 -mt-6 w-10 h-10 md:w-14 md:h-14 flex items-center justify-center bg-white/5 backdrop-blur-sm rounded-full shadow-lg border border-white/10 p-2 md:p-3 hover:bg-white/20 hover:border-accent transition-all duration-300 cursor-pointer group">
            <img src={tech.url} alt={tech.name} className="w-full h-full object-contain pointer-events-none opacity-80 group-hover:opacity-100" />
            <div className="hidden md:block absolute -top-10 left-1/2 -translate-x-1/2 px-3 py-1 bg-black/80 text-white text-xs font-bold rounded border border-white/10 opacity-0 group-hover:opacity-100 transition-all pointer-events-none">{tech.name}</div>
          </div>
        ))}
      </div>
    </div>
  );
};
export default TechSphere;
```

